import random
import itertools

n = 19
min_edges = 32

def has_short_cycle(edges_set, max_len=6):
    """Check if the graph has any cycle of length <= max_len"""
    # Build adjacency
    adj = [[] for _ in range(n)]
    for u, v in edges_set:
        adj[u].append(v)
        adj[v].append(u)

    # For each starting vertex, do BFS/DFS to find cycles
    for start in range(n):
        # DFS to find cycles
        stack = [(start, [start])]
        visited_paths = set()
        while stack:
            v, path = stack.pop()
            for nb in adj[v]:
                if nb == path[-2] if len(path) >= 2 else False:
                    continue
                if nb in path:
                    # Found a cycle
                    idx = path.index(nb)
                    cycle_len = len(path) - idx
                    if cycle_len <= max_len:
                        return True, cycle_len, path[idx:] + [nb]
                else:
                    if len(path) < max_len:
                        stack.append((nb, path + [nb]))
    return False, None, None

def is_3_colorable(edges_set):
    """Check if graph is 3-colorable using backtracking"""
    adj = [[] for _ in range(n)]
    for u, v in edges_set:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = set()
        for nb in adj[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0), colors

