        adj[v].append(u)

    # For each vertex, BFS to find cycles
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        q = deque([start])
        while q:
            v = q.popleft()
            if dist[v] >= max_len:
                continue
