                    # Found a cycle
                    # The cycle length is dist[v] + dist[nb] + 1
                    cycle_len = dist[v] + dist[nb] + 1
                    if cycle_len <= max_len:
                        return True
                else:
                    dist[nb] = dist[v] + 1
                    parent[nb] = v
                    q.append(nb)
    return False

